import { beforeAll,afterAll,afterEach,it,expect } from 'vitest';
import { Pool } from 'pg';
import { randomUUID } from 'node:crypto';
import { io,type Socket } from 'socket.io-client';
import { MeSchema,RoomAckSchema,type RoomSnapshot } from '@virtual-city/contracts';
import { restaurantWorldVersion,restaurantTables,restaurantServicePolicy } from '@virtual-city/restaurant-world';
import { readConfig } from '../../apps/platform-api/src/shared/config/environment';
import { createApp } from '../../apps/platform-api/src/app';
import { migrate } from '../../apps/platform-api/src/shared/database/migrations';
let admin:Pool,pool:Pool,app:Awaited<ReturnType<typeof createApp>>,url:string,config:ReturnType<typeof readConfig>;
const clients:Socket[]=[],schema='restaurant_test_'+randomUUID().replaceAll('-',''),origin='http://127.0.0.1:3300',organizers=new Set<string>();let serial=0,offset=0,stepClock=0;
async function open(){app=await createApp(config,pool,false,{now:()=>Date.now()+offset+(stepClock>0?stepClock++:0),events:{organizers:{permits:async(_db,actor,world)=>world==='restaurant'&&organizers.has(actor.accountId)}}});await app.app.listen(0,'127.0.0.1');url=await app.app.getUrl();}
beforeAll(async()=>{
 const connection=new URL(process.env.TEST_DATABASE_URL??'');if(!['localhost','127.0.0.1','[::1]'].includes(connection.hostname)||!/^virtual_city_test(?:_|$)/.test(connection.pathname.slice(1)))throw Error('Refusing non-local/non-test database');
 admin=new Pool({connectionString:connection.toString()});await admin.query(`CREATE SCHEMA "${schema}"`);connection.searchParams.set('options','-c search_path='+schema);pool=new Pool({connectionString:connection.toString()});await migrate(pool);
 config=readConfig({NODE_ENV:'test',DATABASE_URL:connection.toString(),SESSION_SECRET:'restaurant-test-session-key-'.repeat(2),WEB_ORIGIN:origin,LOCAL_RESTAURANT_WORLD:'1',SAFETY_EVIDENCE_KEY:'67'.repeat(32)});await open();
});
afterEach(async()=>{for(const client of clients.splice(0))client.close();await app.worlds.registry.setEnabled('restaurant',false);await app.rooms.maintain();await pool.query('DELETE FROM engine_events');organizers.clear();offset=0;stepClock=0;});
afterAll(async()=>{await app?.app.close();await pool?.end();if(admin){await admin.query(`DROP SCHEMA IF EXISTS "${schema}" CASCADE`);await admin.end();}});
async function visitor(){const response=await app.http.inject({method:'POST',url:'/v1/session/guest',remoteAddress:'127.61.0.'+(++serial),headers:{origin},payload:{requestId:randomUUID(),displayName:'Dining Visitor',avatarKey:'mint'}});expect(response.statusCode).toBe(201);const me=MeSchema.parse(response.json()),cookie=String(response.headers['set-cookie']).split(';')[0],socket=io(url,{forceNew:true,autoConnect:false,reconnection:false,transports:['websocket'],transportOptions:{websocket:{localAddress:'127.62.0.'+serial}},extraHeaders:{origin,cookie},auth:{schemaVersion:1,csrfToken:me.csrfToken}});clients.push(socket);await new Promise<void>((resolve,reject)=>{socket.once('connect',()=>resolve());socket.once('connect_error',reject);socket.connect();});return {me,cookie,socket};}
const join=(roomId?:string)=>({schemaVersion:1,requestId:randomUUID(),worldSlug:'restaurant',worldVersion:restaurantWorldVersion,sceneVersion:'1.0.0',motionVersion:1,...roomId?{roomId}:{}});
const own=(room:RoomSnapshot)=>({schemaVersion:1,requestId:randomUUID(),epoch:room.epoch,roomId:room.roomId,membershipId:room.membershipId});
it('dining party observations require authentication',async()=>{
 expect((await app.http.inject({method:'POST',url:'/v1/reservations/parties/view',headers:{origin},payload:{schemaVersion:1,worldSlug:'restaurant',source:{epoch:randomUUID(),roomId:randomUUID(),membershipId:randomUUID()}}})).statusCode).toBe(401);
});
it('Restaurant own staffing state requires authentication',async()=>{
 expect((await app.http.inject({url:'/v1/staff/state'})).statusCode).toBe(401);
});
it('kitchen pass actions require authentication and do not accept anonymous course choices',async()=>{
 expect((await app.http.inject({method:'POST',url:`/v1/orders/${randomUUID()}/pick-up`,headers:{origin},payload:{schemaVersion:1,source:{epoch:randomUUID(),roomId:randomUUID(),membershipId:randomUUID()},expectedVersion:0,courseKey:'starter'}})).statusCode).toBe(401);
});
it('private dinner invitation inbox requires authentication',async()=>{
 expect((await app.http.inject({url:'/v1/reservations/dinner-invitations'})).statusCode).toBe(401);
});
it('Restaurant requires an independent flag; catalog and room reads allocate nothing',async()=>{
 const v=await visitor(),denied=RoomAckSchema.parse(await v.socket.timeout(5000).emitWithAck('room.join',join()));expect(denied.ok).toBe(false);if(!denied.ok)expect(denied.error.code).toBe('WORLD_UNAVAILABLE');
 await app.worlds.registry.setEnabled('restaurant',true);const catalog=await app.http.inject({url:'/v1/worlds',headers:{cookie:v.cookie}});expect(catalog.json().worlds.find((item:{slug:string})=>item.slug==='restaurant')).toMatchObject({kind:'world',capacity:10,availability:'available',capabilities:['presence','seating','events','portals','hospitality']});
 expect((await app.http.inject({url:'/v1/worlds/restaurant/rooms',headers:{cookie:v.cookie}})).json().rooms).toEqual([]);expect((await app.http.inject({url:'/v1/me/room',headers:{cookie:v.cookie}})).json().snapshot).toBeNull();expect((await app.http.inject({url:'/v1/worlds/restaurant/rooms'})).statusCode).toBe(401);
});
it('actual ten-place admission and eight exclusive dining chairs preserve identity without service authority',async()=>{
 await app.worlds.registry.setEnabled('restaurant',true);const users:Awaited<ReturnType<typeof visitor>>[]=[],rooms:RoomSnapshot[]=[];
 for(let n=0;n<10;n++){const v=await visitor();users.push(v);const ack=RoomAckSchema.parse(await v.socket.timeout(5000).emitWithAck('room.join',join(rooms[0]?.roomId)));if(!ack.ok||ack.result.type!=='snapshot')throw Error('Missing Restaurant admission');rooms.push(ack.result);expect(ack.result.capacity).toBe(10);expect(ack.result.self.accountId).toBe(v.me.profile.id);}
 const race=await Promise.all(users.map((v,index)=>v.socket.timeout(5000).emitWithAck('seat.claim',{...own(rooms[index]),seatId:'seat-1'}).then(value=>RoomAckSchema.parse(value))));expect(race.filter(ack=>ack.ok)).toHaveLength(1);
 const winner=race.findIndex(ack=>ack.ok);let next=0;for(const seatId of restaurantTables.flatMap(table=>table.seatIds).slice(1)){while(next===winner)next++;expect(RoomAckSchema.parse(await users[next].socket.timeout(5000).emitWithAck('seat.claim',{...own(rooms[next]),seatId})).ok).toBe(true);next++;}
 const snapshot=(await app.http.inject({url:'/v1/me/room',headers:{cookie:users[winner].cookie}})).json().snapshot;expect(snapshot.occupancy).toBe(10);expect(snapshot.seats).toHaveLength(8);expect(snapshot.seats.filter((seat:{state:string})=>seat.state==='occupied')).toHaveLength(8);
 const extra=await visitor(),full=RoomAckSchema.parse(await extra.socket.timeout(5000).emitWithAck('room.join',join(rooms[0].roomId)));expect(full.ok).toBe(false);if(!full.ok)expect(full.error.code).toBe('ROOM_FULL');
 const actor=users[winner],headers={origin,cookie:actor.cookie,'x-csrf-token':actor.me.csrfToken,'idempotency-key':randomUUID()};expect((await app.http.inject({url:'/v1/staff/shift',headers:{cookie:actor.cookie}})).json().shift).toBeNull();
 expect((await app.http.inject({method:'POST',url:'/v1/staff/shifts',headers,payload:{schemaVersion:1,source:{epoch:rooms[winner].epoch,roomId:rooms[winner].roomId,membershipId:rooms[winner].membershipId},policyVersion:'1.0.0'}})).statusCode).toBe(409);
 await app.worlds.registry.setEnabled('restaurant',false);await app.rooms.maintain();expect((await app.http.inject({url:'/v1/me/room',headers:{cookie:actor.cookie}})).json().snapshot).toBeNull();
});
type Visitor=Awaited<ReturnType<typeof visitor>>;
const source=(room:RoomSnapshot)=>({epoch:room.epoch,roomId:room.roomId,membershipId:room.membershipId});
const headers=(v:Visitor,key=randomUUID())=>({origin,cookie:v.cookie,'x-csrf-token':v.me.csrfToken,'idempotency-key':key});
async function enter(v:Visitor,roomId?:string){const ack=RoomAckSchema.parse(await v.socket.timeout(5000).emitWithAck('room.join',join(roomId)));if(!ack.ok||ack.result.type!=='snapshot')throw Error('Missing Restaurant admission');return ack.result;}
async function slot(author:Visitor,resource='garden-table'){
 organizers.add(author.me.profile.id);const at=Date.now()+offset;
 const response=await app.http.inject({method:'POST',url:'/v1/events',headers:headers(author),payload:{schemaVersion:1,worldSlug:'restaurant',policyVersion:'1.0.0',title:'Virtual dining slot',audience:'silent',visibility:'listed',capacity:4,resourceKey:resource,schedule:{schemaVersion:1,timeZone:'Asia/Ho_Chi_Minh',opensAt:new Date(at+60000).toISOString(),startsAt:new Date(at+600000).toISOString(),checkInClosesAt:new Date(at+1200000).toISOString(),endsAt:new Date(at+1800000).toISOString()}}});expect(response.statusCode).toBe(201);return response.json().event;
}
async function checkedParty(owner:Visitor,size=2){const event=await slot(owner);offset+=61000;const hold=await app.http.inject({method:'POST',url:'/v1/reservations',headers:headers(owner),payload:{schemaVersion:1,eventId:event.id,partySize:size}});expect(hold.statusCode).toBe(201);const id=hold.json().reservation.id;expect((await app.http.inject({method:'POST',url:`/v1/reservations/${id}/confirm`,headers:headers(owner),payload:{schemaVersion:1}})).statusCode).toBe(200);const room=await enter(owner);expect((await app.http.inject({method:'POST',url:`/v1/reservations/${id}/check-in`,headers:headers(owner),payload:{schemaVersion:1,source:source(room)}})).statusCode).toBe(200);return {id,event,room};}
const party=(v:Visitor,id:string,action:string,body:Record<string,unknown>,key=randomUUID())=>app.http.inject({method:'POST',url:`/v1/reservations/${id}/party/${action}`,headers:headers(v,key),payload:{...action==='leave'?{}:{expectedRevision:0},...body}});
const parties=(v:Visitor,room:RoomSnapshot)=>app.http.inject({method:'POST',url:'/v1/reservations/parties/view',headers:headers(v),payload:{schemaVersion:1,worldSlug:'restaurant',source:source(room)}});
async function befriend(a:Visitor,b:Visitor){const code=(await app.http.inject({url:'/v1/social/me',headers:{cookie:b.cookie}})).json().contactCode;const requested=await app.http.inject({method:'POST',url:'/v1/friends/requests',headers:headers(a),payload:{contactCode:code}});expect(requested.statusCode).toBe(200);expect((await app.http.inject({method:'POST',url:`/v1/friends/requests/${requested.json().id}/respond`,headers:headers(b),payload:{action:'accept'}})).statusCode).toBe(200);}
const dinnerSettings=(v:Visitor,allowInvitations:boolean)=>app.http.inject({method:'PATCH',url:'/v1/me/invitations/settings',headers:headers(v),payload:{schemaVersion:1,allowInvitations}});
const dinnerInbox=(v:Visitor)=>app.http.inject({url:'/v1/reservations/dinner-invitations',headers:{cookie:v.cookie}});
const dinnerRespond=(v:Visitor,id:string,action:string,key=randomUUID())=>app.http.inject({method:'POST',url:`/v1/reservations/dinner-invitations/${id}/respond`,headers:headers(v,key),payload:{schemaVersion:1,action}});
async function dinnerOffer(owner:Visitor,peer:Visitor,setup:Awaited<ReturnType<typeof checkedParty>>,key=randomUUID()) {const state=(await app.http.inject({url:'/v1/reservations/parties/me',headers:{cookie:owner.cookie}})).json();return app.http.inject({method:'POST',url:`/v1/reservations/${setup.id}/party/invitations`,headers:headers(owner,key),payload:{schemaVersion:1,source:source(setup.room),expectedRevision:state.revision,recipientId:peer.me.profile.id}});}
async function privateDinner(){await app.worlds.registry.setEnabled('restaurant',true);const owner=await visitor(),peer=await visitor(),setup=await checkedParty(owner);await befriend(owner,peer);await dinnerSettings(peer,true);expect((await party(owner,setup.id,'open',{schemaVersion:1,source:source(setup.room),open:true,visibility:'invited'})).statusCode).toBe(200);return {owner,peer,setup};}
it('private dinner city discovery retains public room/schedule activity without disclosing private offer,party or participant identifiers',async()=>{
 const {owner,peer,setup}=await privateDinner(),sent=(await dinnerOffer(owner,peer,setup)).json(),outsider=await visitor();await dinnerRespond(peer,sent.id,'accept');const view=await app.http.inject({url:'/v1/discovery',headers:{cookie:outsider.cookie}});expect(view.statusCode).toBe(200);expect(view.json().featured.find((item:{worldSlug:string})=>item.worldSlug==='restaurant')).toMatchObject({reason:'occupied',usedPlaces:1,eventState:'upcoming'});for(const privateId of [sent.id,setup.id,owner.me.profile.id,peer.me.profile.id])expect(view.body).not.toContain(privateId);expect(view.body).not.toMatch(/confirmedCount|recipient|party_visibility|reservationId/);
});
it('private dinner requires friendship and recipient opt-in;acceptance allocates no attendance,room,chair or RSVP and discovery excludes the private party',async()=>{
 await app.worlds.registry.setEnabled('restaurant',true);const owner=await visitor(),peer=await visitor(),stranger=await visitor(),setup=await checkedParty(owner);expect((await party(owner,setup.id,'open',{schemaVersion:1,source:source(setup.room),open:true,visibility:'invited'})).statusCode).toBe(200);
 expect((await dinnerOffer(owner,peer,setup)).statusCode).toBe(404);await befriend(owner,peer);expect((await dinnerOffer(owner,peer,setup)).statusCode).toBe(404);await dinnerSettings(peer,true);const key=randomUUID(),sent=await dinnerOffer(owner,peer,setup,key);expect(sent.statusCode).toBe(201);const id=sent.json().id;expect((await dinnerOffer(owner,peer,setup,key)).json()).toEqual(sent.json());expect((await dinnerRespond(stranger,id,'accept')).statusCode).toBe(404);expect((await dinnerRespond(owner,id,'accept')).statusCode).toBe(404);
 const pending=(await dinnerInbox(peer)).json();expect(pending.items[0].offer).toMatchObject({reservationId:null,roomId:null});expect(JSON.stringify(pending)).not.toContain(owner.me.profile.id);expect(JSON.stringify(pending)).not.toContain(setup.id);expect((await dinnerInbox(stranger)).json().items).toEqual([]);
 const memberships=app.rooms.diagnostics().memberships,acceptKey=randomUUID(),accepted=await Promise.all(Array.from({length:6},()=>dinnerRespond(peer,id,'accept',acceptKey)));expect(accepted.every(r=>r.statusCode===200&&r.json().phase==='ACCEPTED')).toBe(true);expect(app.rooms.diagnostics().memberships).toBe(memberships);expect((await app.http.inject({url:'/v1/me/room',headers:{cookie:peer.cookie}})).json().snapshot).toBeNull();expect((await pool.query('SELECT count(*)::int AS n FROM engine_event_rsvps WHERE event_id=$1',[setup.event.id])).rows[0].n).toBe(0);expect((await pool.query('SELECT count(*)::int AS n FROM engine_reservation_members WHERE reservation_id=$1',[setup.id])).rows[0].n).toBe(1);
 expect((await dinnerInbox(peer)).json().items[0].offer).toMatchObject({reservationId:setup.id,roomId:setup.room.roomId});const outside=await enter(stranger,setup.room.roomId);expect((await parties(stranger,outside)).json()).toMatchObject({items:[],truncated:false});expect((await party(stranger,setup.id,'join',{schemaVersion:1,source:source(outside)})).statusCode).toBe(404);const room=await enter(peer,setup.room.roomId);expect((await parties(peer,room)).json().items[0]).toMatchObject({id:setup.id,visibility:'invited',confirmedCount:1,joined:false});expect((await party(peer,setup.id,'join',{schemaVersion:1,source:source(room)})).statusCode).toBe(200);expect((await parties(owner,setup.room)).json().items[0].confirmedCount).toBe(2);
 const catalog=await app.http.inject({url:'/v1/events?worldSlug=restaurant',headers:{cookie:stranger.cookie}});expect(catalog.body).not.toContain(setup.id);expect(catalog.body).not.toContain(id);expect(catalog.body).not.toContain(peer.me.profile.id);expect(catalog.json().items.some((e:{id:string})=>e.id===setup.event.id)).toBe(true);expect((await pool.query('SELECT count(*)::int AS n FROM engine_reservation_invite_mutations WHERE request_id=$1',[acceptKey])).rows[0].n).toBe(1);
});
it('private dinner decline,cancel,opt-out,mode changes and stop revoke attendance without resurrecting prior acceptance',async()=>{
 const {owner,peer,setup}=await privateDinner(),room=await enter(peer,setup.room.roomId);let sent=(await dinnerOffer(owner,peer,setup)).json();expect((await dinnerRespond(peer,sent.id,'decline')).json().phase).toBe('DECLINED');expect((await dinnerRespond(peer,sent.id,'accept')).json().phase).toBe('DECLINED');sent=(await dinnerOffer(owner,peer,setup)).json();await dinnerRespond(peer,sent.id,'accept');await party(peer,setup.id,'join',{schemaVersion:1,source:source(room)});expect((await dinnerRespond(owner,sent.id,'cancel')).json().phase).toBe('CANCELLED');expect((await parties(peer,room)).json().items).toEqual([]);
 sent=(await dinnerOffer(owner,peer,setup)).json();await dinnerRespond(peer,sent.id,'accept');expect((await dinnerSettings(peer,false)).statusCode).toBe(200);await dinnerSettings(peer,true);expect((await dinnerRespond(peer,sent.id,'accept')).json().phase).toBe('CANCELLED');expect((await parties(peer,room)).json().items).toEqual([]);
 const revision=(await app.http.inject({url:'/v1/reservations/parties/me',headers:{cookie:owner.cookie}})).json().revision;expect((await party(owner,setup.id,'open',{schemaVersion:1,source:source(setup.room),open:true,visibility:'room',expectedRevision:revision})).statusCode).toBe(200);expect((await parties(peer,room)).json().items[0].joined).toBe(false);expect((await party(peer,setup.id,'join',{schemaVersion:1,source:source(room)})).statusCode).toBe(200);const next=(await app.http.inject({url:'/v1/reservations/parties/me',headers:{cookie:owner.cookie}})).json().revision;await party(owner,setup.id,'open',{schemaVersion:1,source:source(setup.room),open:true,visibility:'invited',expectedRevision:next});expect((await parties(peer,room)).json().items).toEqual([]);
 sent=(await dinnerOffer(owner,peer,setup)).json();await dinnerRespond(peer,sent.id,'accept');expect((await app.http.inject({method:'POST',url:'/v1/reservations/parties/stop',headers:headers(peer),payload:{schemaVersion:1}})).statusCode).toBe(200);expect((await dinnerRespond(peer,sent.id,'accept')).json().phase).toBe('CANCELLED');expect((await parties(peer,room)).json().items).toEqual([]);
});
it('private dinner block and unfriend revoke offers atomically;callback failure rolls back the block and offer together',async()=>{
 const {owner,peer,setup}=await privateDinner(),created=(await dinnerOffer(owner,peer,setup)).json();await dinnerRespond(peer,created.id,'accept');const room=await enter(peer,setup.room.roomId);await party(peer,setup.id,'join',{schemaVersion:1,source:source(room)});
 await pool.query("CREATE FUNCTION reject_dinner_withdraw() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.phase='CANCELLED' THEN RAISE EXCEPTION 'synthetic dinner withdrawal outage'; END IF;RETURN NEW;END $$");await pool.query('CREATE TRIGGER reject_dinner_withdraw BEFORE UPDATE ON engine_reservation_invitations FOR EACH ROW EXECUTE FUNCTION reject_dinner_withdraw()');try{expect((await app.http.inject({method:'POST',url:'/v1/blocks',headers:headers(peer),payload:{targetId:owner.me.profile.id,blocked:true}})).statusCode).toBe(503);expect((await pool.query('SELECT phase FROM engine_reservation_invitations WHERE id=$1',[created.id])).rows[0].phase).toBe('ACCEPTED');expect((await parties(peer,room)).json().items[0].joined).toBe(true);}finally{await pool.query('DROP TRIGGER reject_dinner_withdraw ON engine_reservation_invitations');await pool.query('DROP FUNCTION reject_dinner_withdraw()');}
 expect((await app.http.inject({method:'DELETE',url:'/v1/friends/'+owner.me.profile.id,headers:headers(peer),payload:{}})).statusCode).toBe(200);expect((await dinnerInbox(peer)).json().items[0]).toMatchObject({phase:'CANCELLED',offer:null});expect((await parties(peer,room)).json().items).toEqual([]);await befriend(owner,peer);expect((await dinnerRespond(peer,created.id,'accept')).json().phase).toBe('CANCELLED');const fresh=(await dinnerOffer(owner,peer,setup)).json();expect((await app.http.inject({method:'POST',url:`/v1/reservations/dinner-invitations/${fresh.id}/block`,headers:headers(peer),payload:{schemaVersion:1}})).statusCode).toBe(200);expect((await dinnerInbox(peer)).json().items.every((i:{offer:unknown})=>i.offer===null)).toBe(true);expect((await dinnerOffer(owner,peer,setup)).statusCode).toBe(404);
});
it('private dinner receipt failure rolls back acceptance and offer TTL cannot be renewed by exact retries',async()=>{
 const {owner,peer,setup}=await privateDinner(),key=randomUUID(),sent=(await dinnerOffer(owner,peer,setup,key)).json(),acceptKey=randomUUID();expect(Date.parse(sent.expiresAt)-Date.parse(sent.createdAt)).toBe(120000);await pool.query("CREATE FUNCTION reject_dinner_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.operation='accept' THEN RAISE EXCEPTION 'synthetic dinner receipt outage'; END IF;RETURN NEW;END $$");await pool.query('CREATE TRIGGER reject_dinner_receipt BEFORE INSERT ON engine_reservation_invite_mutations FOR EACH ROW EXECUTE FUNCTION reject_dinner_receipt()');try{expect((await dinnerRespond(peer,sent.id,'accept',acceptKey)).statusCode).toBe(503);expect((await pool.query('SELECT phase FROM engine_reservation_invitations WHERE id=$1',[sent.id])).rows[0].phase).toBe('PENDING');}finally{await pool.query('DROP TRIGGER reject_dinner_receipt ON engine_reservation_invite_mutations');await pool.query('DROP FUNCTION reject_dinner_receipt()');}offset+=120001;expect((await dinnerRespond(peer,sent.id,'accept',acceptKey)).json().phase).toBe('EXPIRED');expect((await dinnerOffer(owner,peer,setup,key)).json()).toEqual({...sent,phase:'EXPIRED'});expect((await dinnerInbox(peer)).json().items[0].offer).toBeNull();
});
it('private dinner event cancellation notifies offer recipients and restart or host departure hides access without forced travel',async()=>{
 const {owner,peer,setup}=await privateDinner(),sent=(await dinnerOffer(owner,peer,setup)).json();await dinnerRespond(peer,sent.id,'accept');expect(RoomAckSchema.parse(await owner.socket.timeout(5000).emitWithAck('room.leave',own(setup.room))).ok).toBe(true);expect((await dinnerInbox(peer)).json().items[0].offer).toBeNull();expect((await dinnerRespond(peer,sent.id,'accept')).json().phase).toBe('ACCEPTED');expect((await app.http.inject({method:'POST',url:`/v1/events/${setup.event.id}/cancel`,headers:headers(owner),payload:{schemaVersion:1,expectedVersion:0}})).statusCode).toBe(200);expect((await dinnerInbox(peer)).json().items[0].phase).toBe('CANCELLED');expect((await app.http.inject({url:'/v1/events/notices',headers:{cookie:peer.cookie}})).json().items.some((n:{eventId:string})=>n.eventId===setup.event.id)).toBe(true);
});
it('private dinner expiry is rechecked after an actual SQL wait and stop racing acceptance cannot restore access',async()=>{
 const {owner,peer,setup}=await privateDinner(),sent=(await dinnerOffer(owner,peer,setup)).json(),key=randomUUID(),db=await pool.connect();let response:ReturnType<typeof dinnerRespond>|undefined;
 try{await db.query('BEGIN');await db.query('SELECT id FROM engine_reservations WHERE id=$1 FOR UPDATE',[setup.id]);response=dinnerRespond(peer,sent.id,'accept',key);void response.then(()=>{});await expect.poll(async()=>Number((await pool.query("SELECT count(*) AS n FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() AND wait_event_type='Lock' AND state='active'")).rows[0].n),{timeout:800,interval:20}).toBeGreaterThan(0);offset+=120001;}finally{await db.query('ROLLBACK');db.release();}expect((await response!).json().phase).toBe('EXPIRED');expect((await dinnerRespond(peer,sent.id,'accept',key)).json().phase).toBe('EXPIRED');
 const next=(await dinnerOffer(owner,peer,setup)).json(),race=await Promise.all([dinnerRespond(peer,next.id,'accept'),app.http.inject({method:'POST',url:'/v1/reservations/parties/stop',headers:headers(peer),payload:{schemaVersion:1}})]);expect(race.every(r=>r.statusCode===200)).toBe(true);expect((await dinnerInbox(peer)).json().items[0]).toMatchObject({phase:'CANCELLED',offer:null});expect((await pool.query("SELECT count(*)::int AS n FROM engine_reservation_members WHERE reservation_id=$1 AND account_id=$2 AND phase='IN'",[setup.id,peer.me.profile.id])).rows[0].n).toBe(0);
});
it('private dinner current visit cannot survive actual owner restart and check-in close expires accepted access',async()=>{
 const {owner,peer,setup}=await privateDinner(),sent=(await dinnerOffer(owner,peer,setup)).json();await dinnerRespond(peer,sent.id,'accept');await app.app.close();await open();await app.worlds.registry.setEnabled('restaurant',true);expect((await dinnerInbox(peer)).json().items[0].offer).toBeNull();expect((await dinnerRespond(peer,sent.id,'decline')).json().phase).toBe('DECLINED');expect(app.rooms.diagnostics().memberships).toBe(0);offset+=1200001;await app.events.maintain();expect((await dinnerInbox(peer)).json().items[0].offer).toBeNull();
});
it('private dinner final acceptance gate checks the response deadline again after the last awaited host-safety proof',async()=>{
 const {owner,peer,setup}=await privateDinner(),sent=(await dinnerOffer(owner,peer,setup)).json(),original=app.rooms.activityAllowed.bind(app.rooms);let calls=0;
 app.rooms.activityAllowed=async(...args)=>{const allowed=await original(...args);if(++calls===2)offset+=120001;return allowed;};
 try{const response=await dinnerRespond(peer,sent.id,'accept');expect(response.statusCode).toBe(200);expect(response.json().phase).toBe('EXPIRED');expect(calls).toBe(2);expect((await pool.query('SELECT phase FROM engine_reservation_invitations WHERE id=$1',[sent.id])).rows[0].phase).toBe('EXPIRED');}finally{app.rooms.activityAllowed=original;}
});
