 expect((await app.http.inject({method:'POST',url:'/v1/blocks',headers:headers(owner),payload:{targetId:winner.me.profile.id,blocked:true}})).statusCode).toBe(200);expect((await parties(winner,room)).json().items).toEqual([]);expect((await party(winner,setup.id,'join',{schemaVersion:1,source:source(room)},key)).json().party.joined).toBe(false);expect((await parties(owner,setup.room)).json().items).toEqual([]);
