 await app.worlds.registry.setEnabled('restaurant',true);const owner=await visitor(),peer=await visitor(),setup=await checkedParty(owner),room=await enter(peer,setup.room.roomId);await party(owner,setup.id,'open',{schemaVersion:1,source:source(setup.room),open:true});await party(peer,setup.id,'join',{schemaVersion:1,source:source(room)});const db=await pool.connect();let blocked:ReturnType<typeof app.http.inject>|undefined;
 try{await db.query('BEGIN');await db.query('SELECT id FROM engine_reservations WHERE id=$1 FOR UPDATE',[setup.id]);blocked=app.http.inject({method:'POST',url:'/v1/blocks',headers:headers(owner),payload:{targetId:peer.me.profile.id,blocked:true}});void blocked.then(()=>{});await expect.poll(async()=>Number((await pool.query("SELECT count(*) AS n FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() AND wait_event_type='Lock' AND state='active'")).rows[0].n),{timeout:800,interval:20}).toBeGreaterThan(0);await db.query('SELECT account_id FROM engine_reservation_members WHERE reservation_id=$1 AND account_id=$2 FOR UPDATE NOWAIT',[setup.id,peer.me.profile.id]);}finally{await db.query('ROLLBACK');db.release();}expect((await blocked!).statusCode).toBe(200);expect((await pool.query('SELECT party_open FROM engine_reservations WHERE id=$1',[setup.id])).rows[0].party_open).toBe(false);
