it('role change receipt failure rolls back role and requeue;stop beats pending start and stale role changes',async()=>{
 await app.worlds.registry.setEnabled('restaurant',true);const worker=await visitor(),room=await enter(worker),key=randomUUID();const raced=await Promise.all([startRole(worker,room,'server',key,0),stopStaff(worker)]);expect([201,409]).toContain(raced[0].statusCode);expect(raced[1].statusCode).toBe(200);expect((await pool.query("SELECT count(*)::int AS n FROM engine_hospitality_shifts WHERE account_id=$1 AND ended_at IS NULL",[worker.me.profile.id])).rows[0].n).toBe(0);expect((await startRole(worker,room,'cook',randomUUID(),0)).statusCode).toBe(409);
 const state=(await staffState(worker)).json(),started=await startRole(worker,room,'server',randomUUID(),state.revision);expect(started.statusCode).toBe(201);const shift=started.json().shift,revision=(await staffState(worker)).json().revision,changeKey=randomUUID();await pool.query("CREATE FUNCTION reject_role_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.operation='role' THEN RAISE EXCEPTION 'synthetic role receipt outage'; END IF;RETURN NEW;END $$");await pool.query('CREATE TRIGGER reject_role_receipt BEFORE INSERT ON engine_hospitality_shift_mutations FOR EACH ROW EXECUTE FUNCTION reject_role_receipt()');try{expect((await switchRole(worker,shift.id,room,'cook',revision,changeKey)).statusCode).toBe(503);expect((await staffState(worker)).json()).toMatchObject({revision,shift:{id:shift.id,role:'server'}});}finally{await pool.query('DROP TRIGGER reject_role_receipt ON engine_hospitality_shift_mutations');await pool.query('DROP FUNCTION reject_role_receipt()');}
 expect((await switchRole(worker,shift.id,room,'cook',revision,changeKey)).statusCode).toBe(200);const now=(await staffState(worker)).json().revision;await stopStaff(worker);expect((await switchRole(worker,shift.id,room,'server',now)).statusCode).toBe(409);expect((await switchRole(worker,shift.id,room,'cook',revision,changeKey)).json().shift.phase).toBe('ended');
});
it('two service places are policy capacity,stop remains available after leave/closure,and disconnect grace ends role authority',async()=>{
 await app.worlds.registry.setEnabled('restaurant',true);const a=await visitor(),b=await visitor(),c=await visitor(),ra=await enter(a),rb=await enter(b,ra.roomId),rc=await enter(c,ra.roomId);expect((await startRole(a,ra,'server')).statusCode).toBe(201);expect((await startRole(b,rb,'cook')).statusCode).toBe(201);expect((await startRole(c,rc,'server')).statusCode).toBe(409);a.socket.close();await new Promise(resolve=>setTimeout(resolve,60));offset+=15001;await app.hospitality.maintain();expect((await staffState(a)).json().shift).toMatchObject({phase:'ended',reason:'disconnected'});expect((await startRole(c,rc,'server')).statusCode).toBe(201);expect(RoomAckSchema.parse(await c.socket.timeout(5000).emitWithAck('room.leave',own(rc))).ok).toBe(true);await app.worlds.registry.setEnabled('restaurant',false);expect((await stopStaff(c)).statusCode).toBe(200);expect((await stopStaff(b)).statusCode).toBe(200);
});
it('a trusted clock advancing on every read still creates exactly a four-hour shift from one timestamp',async()=>{
 stepClock=1;await app.worlds.registry.setEnabled('restaurant',true);const actor=await visitor(),room=await enter(actor),started=await startRole(actor,room,'server');expect(started.statusCode).toBe(201);const shift=started.json().shift;expect(Date.parse(shift.expiresAt)-Date.parse(shift.startedAt)).toBe(4*3600000);expect((await stopStaff(actor)).statusCode).toBe(200);
});
it('actual restart ends old role authority,old receipts remain ended,and own role history exports and erases without peer data',async()=>{
 await app.worlds.registry.setEnabled('restaurant',true);const actor=await visitor(),room=await enter(actor),key=randomUUID(),started=await startRole(actor,room,'cook',key,0);expect(started.statusCode).toBe(201);const shift=started.json().shift;await app.app.close();await open();await app.worlds.registry.setEnabled('restaurant',true);const state=(await staffState(actor)).json();expect(state.shift).toMatchObject({id:shift.id,role:'cook',phase:'ended',reason:'restart'});expect(state.revision).toBe(2);expect((await startRole(actor,room,'cook',key,0)).json().shift.phase).toBe('ended');expect((await switchRole(actor,shift.id,room,'server',state.revision)).statusCode).toBe(409);expect((await app.http.inject({url:'/v1/staff/state?accountId='+actor.me.profile.id,headers:{cookie:actor.cookie}})).statusCode).toBe(422);
 const exported=await app.http.inject({url:'/v1/me/export',headers:{cookie:actor.cookie}});expect(exported.statusCode).toBe(200);expect(exported.json().domains.hospitality.shifts[0]).toMatchObject({role:'cook',phase:'ended'});expect(JSON.stringify(exported.json().domains.hospitality)).not.toMatch(/membership_id|owner_epoch|fingerprint/);expect((await app.http.inject({method:'DELETE',url:'/v1/me',headers:headers(actor),payload:{}})).statusCode).toBe(200);expect((await pool.query('SELECT count(*)::int AS n FROM engine_hospitality_consent WHERE account_id=$1',[actor.me.profile.id])).rows[0].n).toBe(0);expect((await pool.query('SELECT count(*)::int AS n FROM engine_hospitality_shifts WHERE account_id=$1',[actor.me.profile.id])).rows[0].n).toBe(0);
});
async function serviceParty(){await app.worlds.registry.setEnabled('restaurant',true);const diner=await visitor(),cook=await visitor(),server=await visitor(),d=await enter(diner),c=await enter(cook,d.roomId),s=await enter(server,d.roomId);expect(RoomAckSchema.parse(await diner.socket.timeout(5000).emitWithAck('seat.claim',{...own(d),seatId:'seat-1'})).ok).toBe(true);expect((await startRole(cook,c,'cook')).statusCode).toBe(201);expect((await startRole(server,s,'server')).statusCode).toBe(201);const placed=await app.http.inject({method:'POST',url:'/v1/orders',headers:headers(diner),payload:{schemaVersion:1,source:source(d),policyVersion:restaurantServicePolicy.version,itemKey:'dinner'}});expect(placed.statusCode).toBe(201);return {diner,cook,server,d,c,s,order:placed.json().order as {id:string;version:number;phase:string}};}
const courseAct=(v:Visitor,room:RoomSnapshot,id:string,action:string,version:number,extra:Record<string,unknown>={},key=randomUUID())=>app.http.inject({method:'POST',url:`/v1/orders/${id}/${action}`,headers:headers(v,key),payload:{schemaVersion:1,source:source(room),expectedVersion:version,...extra}});
it('two actual voluntary workers coordinate all three courses;server-clock preparation,matching passes and customer completion commit once',async()=>{
 const p=await serviceParty(),menu=await app.http.inject({method:'POST',url:'/v1/orders/menu',headers:headers(p.diner),payload:{schemaVersion:1,source:source(p.d)}});expect(menu.statusCode).toBe(200);expect(menu.json().items[0].courseCount).toBe(3);let version=0;
 for(const [index,key]of ['starter','main','dessert'].entries()){
  expect((await courseAct(p.cook,p.c,p.order.id,'claim',version++)).statusCode).toBe(200);expect((await courseAct(p.server,p.s,p.order.id,'prepare',version)).statusCode).toBe(404);expect((await courseAct(p.cook,p.c,p.order.id,'prepare',version++)).statusCode).toBe(200);expect((await courseAct(p.cook,p.c,p.order.id,'ready',version)).statusCode).toBe(409);offset+=2001;expect((await courseAct(p.cook,p.c,p.order.id,'ready',version++)).statusCode).toBe(200);
  expect((await courseAct(p.cook,p.c,p.order.id,'pick-up',version,{courseKey:key})).statusCode).toBe(404);expect((await courseAct(p.server,p.s,p.order.id,'serve',version)).statusCode).toBe(404);expect((await courseAct(p.server,p.s,p.order.id,'pick-up',version,{courseKey:'wrong-course'})).statusCode).toBe(409);expect((await courseAct(p.server,p.s,p.order.id,'pick-up',version,{courseKey:key,score:999})).statusCode).toBe(422);
  const receipt=randomUUID(),passes=await Promise.all(Array.from({length:8},()=>courseAct(p.server,p.s,p.order.id,'pick-up',version,{courseKey:key},receipt)));expect(passes.every(response=>response.statusCode===200)).toBe(true);version++;expect(passes[0].json().order).toMatchObject({version,assignedToMe:true,phase:'READY'});expect((await pool.query("SELECT count(*)::int AS n FROM engine_hospitality_mutations WHERE order_id=$1 AND operation='pick-up'",[p.order.id])).rows[0].n).toBe(index+1);
  expect((await courseAct(p.cook,p.c,p.order.id,'serve',version)).statusCode).toBe(404);const served=await courseAct(p.server,p.s,p.order.id,'serve',version++);expect(served.statusCode).toBe(200);expect(served.json().order).toMatchObject({version,phase:index===2?'SERVED':'PENDING',service:{coursesServed:index+1}});
 }
 const completions=await Promise.all(Array.from({length:8},()=>app.http.inject({method:'POST',url:`/v1/orders/${p.order.id}/complete`,headers:headers(p.diner),payload:{schemaVersion:1,expectedVersion:version}})));expect(completions.every(response=>response.statusCode===200&&response.json().order.phase==='COMPLETED')).toBe(true);expect((await pool.query('SELECT count(*)::int AS n FROM engine_hospitality_courses WHERE order_id=$1',[p.order.id])).rows[0].n).toBe(3);expect((await pool.query('SELECT count(*)::int AS n FROM engine_hospitality_completions WHERE order_id=$1',[p.order.id])).rows[0].n).toBe(1);expect((await pool.query('SELECT count(*)::int AS n FROM engine_hospitality_outbox o JOIN engine_hospitality_completions c ON c.id=o.event_id WHERE c.order_id=$1',[p.order.id])).rows[0].n).toBe(1);const mine=await app.http.inject({url:'/v1/orders/mine',headers:{cookie:p.diner.cookie}});expect(mine.statusCode).toBe(200);expect(mine.json().items.filter((order:{id:string})=>order.id===p.order.id)).toHaveLength(1);expect((await app.http.inject({url:'/v1/orders/mine',headers:{cookie:p.cook.cookie}})).json().items).toEqual([]);expect(mine.body).not.toContain(p.cook.me.profile.id);expect(mine.body).not.toContain(p.server.me.profile.id);
});
it('pass receipt failure rolls back transfer;blocking workers prevents pickup without serving a course',async()=>{
 const p=await serviceParty();await courseAct(p.cook,p.c,p.order.id,'claim',0);await courseAct(p.cook,p.c,p.order.id,'prepare',1);offset+=2001;await courseAct(p.cook,p.c,p.order.id,'ready',2);const key=randomUUID();await pool.query("CREATE FUNCTION reject_pass_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.operation='pick-up' THEN RAISE EXCEPTION 'synthetic pass receipt outage'; END IF;RETURN NEW;END $$");await pool.query('CREATE TRIGGER reject_pass_receipt BEFORE INSERT ON engine_hospitality_mutations FOR EACH ROW EXECUTE FUNCTION reject_pass_receipt()');try{expect((await courseAct(p.server,p.s,p.order.id,'pick-up',3,{courseKey:'starter'},key)).statusCode).toBe(503);expect((await pool.query('SELECT assignee_id,version,phase FROM engine_hospitality_orders WHERE id=$1',[p.order.id])).rows[0]).toMatchObject({assignee_id:p.cook.me.profile.id,version:3,phase:'READY'});}finally{await pool.query('DROP TRIGGER reject_pass_receipt ON engine_hospitality_mutations');await pool.query('DROP FUNCTION reject_pass_receipt()');}
 expect((await app.http.inject({method:'POST',url:'/v1/blocks',headers:headers(p.cook),payload:{targetId:p.server.me.profile.id,blocked:true}})).statusCode).toBe(200);expect((await courseAct(p.server,p.s,p.order.id,'pick-up',3,{courseKey:'starter'},key)).statusCode).toBe(404);expect((await pool.query('SELECT count(*)::int AS n FROM engine_hospitality_courses WHERE order_id=$1',[p.order.id])).rows[0].n).toBe(0);
});
it('customer withdrawal racing a matching pass serializes safely and cannot leave a served course or completion',async()=>{
 const p=await serviceParty();await courseAct(p.cook,p.c,p.order.id,'claim',0);await courseAct(p.cook,p.c,p.order.id,'prepare',1);offset+=2001;await courseAct(p.cook,p.c,p.order.id,'ready',2);const race=await Promise.all([courseAct(p.server,p.s,p.order.id,'pick-up',3,{courseKey:'starter'}),app.http.inject({method:'POST',url:`/v1/orders/${p.order.id}/withdraw`,headers:headers(p.diner),payload:{schemaVersion:1,expectedVersion:3}})]);expect([200,404,409]).toContain(race[0].statusCode);expect([200,409]).toContain(race[1].statusCode);let current=(await app.http.inject({url:'/v1/orders/'+p.order.id,headers:{cookie:p.diner.cookie}})).json().order;if(current.phase==='READY'){expect((await app.http.inject({method:'POST',url:`/v1/orders/${p.order.id}/withdraw`,headers:headers(p.diner),payload:{schemaVersion:1,expectedVersion:current.version}})).statusCode).toBe(200);current=(await app.http.inject({url:'/v1/orders/'+p.order.id,headers:{cookie:p.diner.cookie}})).json().order;}expect(current.phase).toBe('CANCELLED');expect((await courseAct(p.server,p.s,p.order.id,'serve',current.version)).statusCode).toBe(404);expect((await pool.query('SELECT count(*)::int AS n FROM engine_hospitality_courses WHERE order_id=$1',[p.order.id])).rows[0].n).toBe(0);expect((await pool.query('SELECT count(*)::int AS n FROM engine_hospitality_completions WHERE order_id=$1',[p.order.id])).rows[0].n).toBe(0);
});
it('served course ledger survives actual Restaurant restart while stranded next-course work cancels without duplicate food or completion',async()=>{
 const p=await serviceParty();await courseAct(p.cook,p.c,p.order.id,'claim',0);await courseAct(p.cook,p.c,p.order.id,'prepare',1);offset+=2001;await courseAct(p.cook,p.c,p.order.id,'ready',2);await courseAct(p.server,p.s,p.order.id,'pick-up',3,{courseKey:'starter'});expect((await courseAct(p.server,p.s,p.order.id,'serve',4)).json().order).toMatchObject({phase:'PENDING',service:{coursesServed:1}});await app.app.close();await open();await app.worlds.registry.setEnabled('restaurant',true);await app.hospitality.maintain();const own=await app.http.inject({url:'/v1/orders/mine',headers:{cookie:p.diner.cookie}});expect(own.statusCode).toBe(200);expect(own.json().items[0]).toMatchObject({id:p.order.id,phase:'CANCELLED',service:{coursesServed:1}});expect((await pool.query('SELECT count(*)::int AS n FROM engine_hospitality_courses WHERE order_id=$1',[p.order.id])).rows[0].n).toBe(1);expect((await pool.query('SELECT count(*)::int AS n FROM engine_hospitality_completions WHERE order_id=$1',[p.order.id])).rows[0].n).toBe(0);expect((await courseAct(p.server,p.s,p.order.id,'serve',4)).statusCode).toBe(409);
});
